// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz parameters: from address, caddress (callee), and a uint value; _tos array length is controlled via bytes to allow empty array
    function testFuzz_property(address from, address caddress, uint8 v, bytes memory tosEncoded) public {
        // We will decode tosEncoded into an address[] possibly empty. Keep domain wide.
        // limit size to avoid OOG during fuzzing but allow empty
        uint maxElems = 8;
        uint elems = tosEncoded.length == 0 ? 0 : (uint(uint8(tosEncoded[0])) % (maxElems + 1));
        address[] memory tos = new address[](elems);
        // fill tos deterministically from from/caddress/v and bytes
        for (uint i = 0; i < elems; i++) {
            // derive pseudo-address from hash to keep inputs varied
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, caddress, v, i, tosEncoded)))));
        }

        bool ok;
        // Call and observe whether transfer reverts or returns true.
        try c.transfer(from, caddress, tos, uint(v)) returns (bool res) {
            ok = res; // should be true if it returned
        } catch {
            ok = false; // reverted
        }

        // GENERAL RULE: reference C reverts exactly when tos.length == 0.
        // So for ALL admissible inputs, if tos.length == 0 then call must revert (ok == false).
        // We restrict nothing else; this property must hold for every fuzz input.
        if (tos.length == 0) {
            // For the reference (correct) contract this is always true; the mutant that removed the require will return true for some inputs and thus fail this assertion.
            assertTrue(ok == false);
        } else {
            // For non-empty lists, both reference and mutant behave similarly (they attempt calls to caddress) — we don't assert here.
            assertTrue(true);
        }
    }
}
